  "BinaryOriginPairs": "query BinaryOriginPairs {\n  Market(\n    distinct_on: [operatorId, venueId]\n    where: {marketType: {_eq: \"BINARY\"}, operatorId: {_is_null: false}, venueId: {_is_null: false}}\n    order_by: [{operatorId: asc}, {venueId: asc}]\n  ) {\n    operatorId\n    venueId\n  }\n}",
