  "VenueByPk": "query VenueByPk($id: String!) {\n  Venue_by_pk(id: $id) {\n    ...VenueFields\n  }\n}\n\nfragment VenueFields on Venue {\n  venueId\n  operatorId\n  marketType\n  feeParams\n  feeRecipientOverride\n  policy\n  signer\n  creationEnabled\n  context\n  createdAtTimestamp\n  updatedAtTimestamp\n  updatedAtBlock\n  marketCount\n  cumulativeQuoteVolume\n  protocolFeesCollected\n  settlementFeesCollected\n  builderFeesCollected\n}",
