  "OracleQuestion": "query OracleQuestion($id: String!) {\n  OracleQuestion_by_pk(id: $id) {\n    ...OracleQuestionFields\n  }\n}\n\nfragment OracleQuestionFields on OracleQuestion {\n  id\n  questionKey\n  scheduler\n  oracleCost\n  bindCount\n  reuseCount\n  createdAtBlock\n  createdAtTimestamp\n}",
  "OracleQuestions": "query OracleQuestions($where: OracleQuestion_bool_exp!, $limit: Int, $offset: Int) {\n  OracleQuestion(\n    where: $where\n    order_by: {createdAtTimestamp: desc}\n    limit: $limit\n    offset: $offset\n  ) {\n    ...OracleQuestionFields\n  }\n}\n\nfragment OracleQuestionFields on OracleQuestion {\n  id\n  questionKey\n  scheduler\n  oracleCost\n  bindCount\n  reuseCount\n  createdAtBlock\n  createdAtTimestamp\n}",
