  "BookTops": "query BookTops($bidWhere: Order_bool_exp!, $askWhere: Order_bool_exp!) {\n  bids: Order(\n    where: $bidWhere\n    distinct_on: market_id\n    order_by: [{market_id: desc}, {price: desc}]\n  ) {\n    market: market_id\n    price\n  }\n  asks: Order(\n    where: $askWhere\n    distinct_on: market_id\n    order_by: [{market_id: asc}, {price: asc}]\n  ) {\n    market: market_id\n    price\n  }\n}",
